// Run after packaged smoke tests have fully exited, before NSIS compression.
// Remove only generated bytecode/browser logs in the disposable distribution.
const fs=require('node:fs'),path=require('node:path'),pkg=require('../package.json');
const project=path.resolve(__dirname,'..'),out=path.resolve(project,pkg.build.directories.output,'win-unpacked');
if(!fs.existsSync(path.join(out,'MediaSail.exe')))throw new Error('Unexpected packaged directory');
let count=0;
function walk(dir,base){for(const entry of fs.readdirSync(dir,{withFileTypes:true})){
 const file=path.resolve(dir,entry.name);if(!file.startsWith(base+path.sep))throw new Error('Cleanup escaped packaged runtime');
 if(entry.isSymbolicLink())continue;
 if(entry.isDirectory()){if(entry.name==='__pycache__'){fs.rmSync(file,{recursive:true,force:true});count++;}else walk(file,base);}
 else if(entry.name.endsWith('.pyc')||entry.name==='debug.log'){fs.unlinkSync(file);count++;}
}}
for(const name of ['runtime','bridge','agent-skill']){
 const base=path.resolve(out,'resources',name);
 if(!base.startsWith(out+path.sep))throw new Error('Invalid packaged cleanup path');
 if(fs.existsSync(base))walk(base,base);
}
console.log(`Removed ${count} generated entries from the disposable packaged copy only`);
